#include "DDCBridge.h"
#include <CoreFoundation/CoreFoundation.h>
#include <IOKit/IOKitLib.h>
#include <CoreAudio/CoreAudio.h>
#include <dlfcn.h>
#include <fcntl.h>
#include <sys/file.h>
#include <unistd.h>
#include <stdio.h>
#include <string.h>
#include <stdlib.h>
#include <ctype.h>
#include <errno.h>

typedef CFTypeRef(*Create)(CFAllocatorRef,io_service_t);
typedef IOReturn(*Access)(CFTypeRef,uint32_t,void*,uint32_t);
typedef IOReturn(*I2C)(CFTypeRef,uint32_t,uint32_t,void*,uint32_t);
typedef struct { CFTypeRef obj; I2C rd,wr; uint64_t registryID; char name[128],uid[256]; } Direct;
typedef struct { CFTypeRef obj; Access rd,wr; unsigned seq,port; char id[96],name[128],uid[256]; } Branch;
static int lockfd=-1;
static void *avlib;
static void *dpLib;
static Create avCreate;
static I2C avRead,avWrite;
static void err(char *b,size_t n,const char *s){if(b&&n)snprintf(b,n,"%s",s);}
static unsigned crc(const uint8_t*b,unsigned bits,unsigned width,unsigned poly){unsigned r=0;for(unsigned i=0;i<bits+width;i++){r<<=1;if(i<bits)r|=(b[i/8]>>(7-i%8))&1;if(r&(1u<<width))r^=poly;}return r;}
static int rd(Branch*x,uint32_t a,void*b,unsigned n){return x->rd(x->obj,a,b,n)==0;}
static int wr(Branch*x,uint32_t a,void*b,unsigned n){return a==0x1000&&n<=48&&x->wr(x->obj,a,b,n)==0 || a==0x201&&n==1&&*(uint8_t*)b==0x10&&x->wr(x->obj,a,b,n)==0;}
static int lock(void){if(lockfd<0)lockfd=open("/private/tmp/lg-monitor-volume-control.lock",O_CREAT|O_RDWR|O_NOFOLLOW,0600);return lockfd>=0&&flock(lockfd,LOCK_EX|LOCK_NB)==0;}
static int directAPI(void){if(avCreate&&avRead&&avWrite)return 1;if(!avlib)avlib=dlopen("/System/Library/Frameworks/IOKit.framework/IOKit",RTLD_LAZY);if(!avlib)return 0;avCreate=(Create)dlsym(avlib,"IOAVServiceCreateWithService");avRead=(I2C)dlsym(avlib,"IOAVServiceReadI2C");avWrite=(I2C)dlsym(avlib,"IOAVServiceWriteI2C");return avCreate&&avRead&&avWrite;}
static int validEDID(const uint8_t *b){unsigned sum=0;for(int i=0;i<128;i++)sum+=b[i];return !memcmp(b,"\0\xff\xff\xff\xff\xff\xff\0",8)&&!(sum&255);}
static int directName(const uint8_t *edid,char *name,size_t cap){for(int d=54;d+18<=126;d+=18)if(!edid[d]&&!edid[d+1]&&!edid[d+2]&&edid[d+3]==0xfc){size_t j=0;for(int k=5;k<18&&j+1<cap;k++){uint8_t c=edid[d+k];if(c==10||c==0)break;name[j++]=isprint(c)?c:' ';}while(j&&name[j-1]==' ')j--;name[j]=0;if(j)return 1;}snprintf(name,cap,"External display");return 1;}
static int directOpen(Direct*x,uint64_t wanted){if(!directAPI())return 0;io_iterator_t it=0;if(IOServiceGetMatchingServices(kIOMainPortDefault,IOServiceMatching("DCPAVServiceProxy"),&it))return 0;io_service_t s;while((s=IOIteratorNext(it))){CFTypeRef loc=IORegistryEntryCreateCFProperty(s,CFSTR("Location"),kCFAllocatorDefault,0);int ext=loc&&CFGetTypeID(loc)==CFStringGetTypeID()&&CFEqual(loc,CFSTR("External"));if(loc)CFRelease(loc);uint64_t rid=0;IORegistryEntryGetRegistryEntryID(s,&rid);if(ext&&(!wanted||rid==wanted)){x->obj=avCreate(kCFAllocatorDefault,s);x->rd=avRead;x->wr=avWrite;x->registryID=rid;}IOObjectRelease(s);if(x->obj)break;}IOObjectRelease(it);return x->obj!=NULL;}
static int directVCP(Direct*x,uint8_t code,int set,uint16_t value,uint16_t*cur,uint16_t*max){if(set){uint8_t p[6]={0x84,3,code,(uint8_t)(value>>8),(uint8_t)value,0};p[5]=0x6e^p[0]^p[1]^p[2]^p[3]^p[4];if(x->wr(x->obj,0x37,0x51,p,sizeof(p)))return 0;}uint8_t q[4]={0x82,1,code,0};q[3]=0x6e^q[0]^q[1]^q[2];if(x->wr(x->obj,0x37,0x51,q,sizeof(q)))return 0;usleep(100000);uint8_t r[11]={0};if(x->rd(x->obj,0x37,0,r,sizeof(r)))return 0;uint8_t check=0x50;for(int i=0;i<11;i++)check^=r[i];if(check||r[0]!=0x6e||r[1]!=0x88||r[2]!=2||r[3]!=0||r[4]!=code)return 0;*max=(r[6]<<8)|r[7];*cur=(r[8]<<8)|r[9];return *max&&*cur<=*max&&(!set||*cur==value);}
static int directByID(const char*id,Direct*x,char*e,size_t ec){if(!id||strncmp(id,"direct:",7)){err(e,ec,"invalid direct display identifier");return 0;}errno=0;char*end=NULL;unsigned long long n=strtoull(id+7,&end,16);if(errno||end==id+7||*end||!n||!directOpen(x,(uint64_t)n)){err(e,ec,"direct display route is no longer available");return 0;}return 1;}
static int openBranch(Branch*x){if(!dpLib)dpLib=dlopen("/System/Library/Frameworks/IOKit.framework/IOKit",RTLD_LAZY);if(!dpLib)return 0;Create create=(Create)dlsym(dpLib,"IODPDeviceCreateWithService");x->rd=(Access)dlsym(dpLib,"IODPDeviceReadDPCD");x->wr=(Access)dlsym(dpLib,"IODPDeviceWriteDPCD");if(!create||!x->rd||!x->wr)return 0;io_iterator_t it=0;if(IOServiceGetMatchingServices(kIOMainPortDefault,IOServiceMatching("DCPDPDeviceProxy"),&it))return 0;io_service_t s;while((s=IOIteratorNext(it))){CFTypeRef loc=IORegistryEntryCreateCFProperty(s,CFSTR("Location"),kCFAllocatorDefault,0);int ext=loc&&CFGetTypeID(loc)==CFStringGetTypeID()&&CFEqual(loc,CFSTR("External"));if(loc)CFRelease(loc);if(ext)x->obj=create(kCFAllocatorDefault,s);IOObjectRelease(s);if(x->obj)break;}IOObjectRelease(it);return x->obj!=NULL;}
static int frag(Branch*x,uint8_t*out,unsigned*len,unsigned*flags){uint8_t b[48];for(int a=0;a<3;a++){if(!rd(x,0x1400,b,48))return 0;unsigned lct=b[0]>>4,h=3+lct/2,n=b[1+(lct/2)]&63,total=h+n;if(lct!=1||h!=3||n<1||total>48)continue;int ok=crc(b,20,4,0x13)==(b[2]&15)&&crc(b+h,(n-1)*8,8,0x1d5)==b[total-1];if(ok){*flags=b[2];*len=n-1;memcpy(out,b+h,*len);uint8_t ack=0x10;return wr(x,0x201,&ack,1);}}
 uint8_t ack=0x10;wr(x,0x201,&ack,1);return 0;}
static int receive(Branch*x,uint8_t*out,unsigned*size,unsigned opcode){unsigned used=0,frags=0;int seq=-1;for(int p=0;p<400;p++){uint8_t irq=0;if(!rd(x,0x201,&irq,1))return 0;if(!(irq&16)){usleep(10000);continue;}uint8_t part[48];unsigned flags=0,n=0;if(!frag(x,part,&n,&flags))return 0;if(flags&0x80){used=0;frags=0;seq=(flags>>4)&1;}else if(!used)return 0;else if(seq!=((flags>>4)&1))return 0;if(++frags>16||used+n>512)return 0;memcpy(out+used,part,n);used+=n;if(flags&0x40){if(seq!=(int)(x->seq&1)||!used||(out[0]&127)!=opcode){used=0;frags=0;continue;}*size=used;return 1;}}return 0;}
static int exchange(Branch*x,const uint8_t*body,unsigned n,uint8_t*out,unsigned*size){if(!n||n>44)return 0;for(int a=0;a<3;a++){uint8_t p[48]={0x10,(uint8_t)(n+1),(uint8_t)(0xc0|((x->seq&1)<<4))};p[2]|=crc(p,20,4,0x13);memcpy(p+3,body,n);p[3+n]=crc(body,n*8,8,0x1d5);if(!wr(x,0x1000,p,n+4))return 0;if(!receive(x,out,size,body[0])){usleep(50000);continue;}x->seq^=1;if((*size&&!(out[0]&128))&&(out[0]&127)==body[0])return 1;if(*size>17&&(out[17]==5||out[17]==6||out[17]==9))usleep(100000);else return 0;}return 0;}
static int listPorts(Branch*x,unsigned*ports,unsigned*count){uint8_t q=1,r[512];unsigned n=0;if(!exchange(x,&q,1,r,&n)||n<18)return 0;unsigned c=r[17]&15,i=18;*count=0;for(unsigned k=0;k<c;k++){if(i+2>n)return 0;uint8_t a=r[i++],b=r[i++];unsigned port=a&15,input=a>>7,peer=(a>>4)&7;if(!input){if(i+18>n)return 0;i+=18;if((b&0x40)&&peer==4)ports[(*count)++]=port;}}return 1;}
static int discoverBranch(Branch*x,unsigned wanted){if(!openBranch(x))return 0;uint8_t chip[2];if(!rd(x,0x507,chip,2))return 0;unsigned ports[16],count=0;if(!listPorts(x,ports,&count))return 0;for(unsigned i=0;i<count;i++)if(ports[i]==wanted){x->port=wanted;return 1;}return 0;}
static int edidName(Branch*x,char*name,size_t cap){uint8_t edid[128]={0};for(unsigned off=0;off<128;off+=16){uint8_t body[]={0x22,(uint8_t)((x->port<<4)|1),0x50,1,(uint8_t)off,0x10,0x50,16},reply[512];unsigned n=0;if(!exchange(x,body,sizeof(body),reply,&n)||n!=19||reply[1]!=x->port||reply[2]!=16)return 0;memcpy(edid+off,reply+3,16);}unsigned sum=0;for(int i=0;i<128;i++)sum+=edid[i];if(memcmp(edid,"\0\xff\xff\xff\xff\xff\xff\0",8)||(sum&255))return 0;for(int d=54;d+18<=126;d+=18)if(!edid[d]&&!edid[d+1]&&!edid[d+2]&&edid[d+3]==0xfc){unsigned j=0;for(int k=5;k<18&&j+1<cap;k++){uint8_t c=edid[d+k];if(c==10||c==0)break;name[j++]=isprint(c)?c:' ';}while(j&&name[j-1]==' ')j--;name[j]=0;if(j)return 1;}snprintf(name,cap,"DisplayPort display");return 1;}
static void audioUIDForName(const char*name,char*out,size_t cap){AudioObjectPropertyAddress a={kAudioHardwarePropertyDevices,kAudioObjectPropertyScopeGlobal,kAudioObjectPropertyElementMain};UInt32 bytes=0;if(AudioObjectGetPropertyDataSize(kAudioObjectSystemObject,&a,0,NULL,&bytes)!=noErr)return;AudioDeviceID*ids=calloc(bytes,sizeof(*ids));if(!ids)return;AudioDeviceID match=0;unsigned matches=0;if(AudioObjectGetPropertyData(kAudioObjectSystemObject,&a,0,NULL,&bytes,ids)==noErr){unsigned c=bytes/sizeof(*ids);for(unsigned i=0;i<c;i++){CFStringRef n=NULL;UInt32 sz=sizeof(n);AudioObjectPropertyAddress p={kAudioObjectPropertyName,kAudioObjectPropertyScopeGlobal,kAudioObjectPropertyElementMain};if(AudioObjectGetPropertyData(ids[i],&p,0,NULL,&sz,&n)==noErr&&n){char b[256];if(CFStringGetCString(n,b,sizeof(b),kCFStringEncodingUTF8)&&strcasecmp(b,name)==0){match=ids[i];matches++;}CFRelease(n);}}}if(matches==1){AudioObjectPropertyAddress p={kAudioDevicePropertyDeviceUID,kAudioObjectPropertyScopeGlobal,kAudioObjectPropertyElementMain};CFStringRef uid=NULL;UInt32 sz=sizeof(uid);if(AudioObjectGetPropertyData(match,&p,0,NULL,&sz,&uid)==noErr&&uid){CFStringGetCString(uid,out,(CFIndex)cap,kCFStringEncodingUTF8);CFRelease(uid);}}free(ids);}
static int ddc(Branch*x,uint8_t code,int set,uint16_t value,uint16_t*cur,uint16_t*max){uint8_t r[512];unsigned n=0;if(set){uint8_t vcp[11]={0x23,(uint8_t)(x->port<<4),0x37,7,0x51,0x84,3,code,(uint8_t)(value>>8),(uint8_t)value,0};uint8_t sum=0x6e;for(int i=4;i<10;i++)sum^=vcp[i];vcp[10]=sum;if(!exchange(x,vcp,sizeof(vcp),r,&n))return 0;}uint8_t cmd[9]={0x23,(uint8_t)(x->port<<4),0x37,5,0x51,0x82,1,code,0};uint8_t sum=0x6e;for(int i=4;i<8;i++)sum^=cmd[i];cmd[8]=sum;if(!exchange(x,cmd,sizeof(cmd),r,&n))return 0;usleep(100000);uint8_t read[]={0x22,(uint8_t)(x->port<<4),0x37,11};if(!exchange(x,read,sizeof(read),r,&n)||n!=14||r[1]!=x->port||r[2]!=11)return 0;uint8_t*v=r+3,xorv=0x50;for(int i=0;i<11;i++)xorv^=v[i];if(v[0]!=0x6e||v[1]!=0x88||v[2]!=2||v[3]!=0||v[4]!=code||xorv)return 0;*max=(v[6]<<8)|v[7];*cur=(v[8]<<8)|v[9];return *max>0&&*cur<=*max&&(!set||*cur==value);}
static int withBranch(const char*id,Branch*x,char*e,size_t ec){if(!lock()){err(e,ec,"another DDC transaction is active");return 0;}memset(x,0,sizeof(*x));unsigned ports[16],count=0,wanted=0;if(!openBranch(x)||!listPorts(x,ports,&count)||!count){err(e,ec,"no connected MST display found");if(x->obj)CFRelease(x->obj);return 0;}if(id){if(strncmp(id,"0:",2)){err(e,ec,"invalid monitor identifier");CFRelease(x->obj);return 0;}errno=0;char*end=NULL;unsigned long parsed=strtoul(id+2,&end,10);if(errno||end==id+2||*end||parsed>15){err(e,ec,"invalid monitor identifier");CFRelease(x->obj);return 0;}wanted=(unsigned)parsed;}else wanted=ports[0];CFRelease(x->obj);memset(x,0,sizeof(*x));if(!discoverBranch(x,wanted)){err(e,ec,"monitor identifier is no longer available");if(x->obj)CFRelease(x->obj);return 0;}snprintf(x->id,sizeof(x->id),"0:%u",x->port);return 1;}
int ddc_discover(DDCMonitor*out,size_t cap,size_t*count,char*e,size_t ec){if(count)*count=0;if(!count||!out||cap==0){err(e,ec,"invalid output buffer");return 0;}if(!lock()){err(e,ec,"another DDC transaction is active");return 0;}size_t found=0;io_iterator_t it=0;if(directAPI()&&!IOServiceGetMatchingServices(kIOMainPortDefault,IOServiceMatching("DCPAVServiceProxy"),&it)){io_service_t s;while((s=IOIteratorNext(it))){CFTypeRef loc=IORegistryEntryCreateCFProperty(s,CFSTR("Location"),kCFAllocatorDefault,0);int ext=loc&&CFGetTypeID(loc)==CFStringGetTypeID()&&CFEqual(loc,CFSTR("External"));if(loc)CFRelease(loc);if(ext&&found<cap){Direct x={0};x.obj=avCreate(kCFAllocatorDefault,s);x.rd=avRead;x.wr=avWrite;if(x.obj){uint8_t edid[128]={0};uint16_t c=0,m=0;uint64_t rid=0;IORegistryEntryGetRegistryEntryID(s,&rid);if(!x.rd(x.obj,0x50,0,edid,sizeof(edid))&&validEDID(edid)&&directVCP(&x,0x62,0,0,&c,&m)){DDCMonitor*r=&out[found++];memset(r,0,sizeof(*r));snprintf(r->id,sizeof(r->id),"direct:%llx",(unsigned long long)rid);directName(edid,r->name,sizeof(r->name));audioUIDForName(r->name,r->audio_uid,sizeof(r->audio_uid));r->current=c;r->maximum=m;}CFRelease(x.obj);}}IOObjectRelease(s);}IOObjectRelease(it);}Branch x={0};if(found<cap&&openBranch(&x)){unsigned ports[16],pc=0;if(listPorts(&x,ports,&pc)){for(unsigned i=0;i<pc&&found<cap;i++){DDCMonitor*r=&out[found];memset(r,0,sizeof(*r));x.port=ports[i];uint16_t c,m;char name[128]={0};if(!edidName(&x,name,sizeof(name))||!ddc(&x,0x62,0,0,&c,&m))continue;found++;snprintf(r->id,sizeof(r->id),"0:%u",x.port);snprintf(r->name,sizeof(r->name),"%s",name);audioUIDForName(name,r->audio_uid,sizeof(r->audio_uid));r->current=c;r->maximum=m;}}CFRelease(x.obj);}if(!found){err(e,ec,"no external display returned a valid EDID and DDC volume reply");return 0;}*count=found;return 1;}
int ddc_get_volume(const char*id,uint16_t*c,uint16_t*m,char*e,size_t ec){if(!c||!m){err(e,ec,"invalid volume output");return 0;}if(id&&!strncmp(id,"direct:",7)){if(!lock())return 0;Direct x={0};if(!directByID(id,&x,e,ec))return 0;int ok=directVCP(&x,0x62,0,0,c,m);CFRelease(x.obj);if(!ok)err(e,ec,"direct DDC volume query failed");return ok;}Branch x;if(!withBranch(id,&x,e,ec))return 0;int ok=ddc(&x,0x62,0,0,c,m);CFRelease(x.obj);if(!ok)err(e,ec,"DDC volume query failed");return ok;}
int ddc_set_volume(const char*id,uint16_t v,char*e,size_t ec){uint16_t c,m;if(id&&!strncmp(id,"direct:",7)){if(!lock())return 0;Direct x={0};if(!directByID(id,&x,e,ec))return 0;int ok=directVCP(&x,0x62,0,0,&c,&m)&&v<=m&&directVCP(&x,0x62,1,v,&c,&m);CFRelease(x.obj);if(!ok)err(e,ec,"direct DDC volume set/readback failed");return ok;}Branch x;if(!withBranch(id,&x,e,ec))return 0;if(!ddc(&x,0x62,0,0,&c,&m)){CFRelease(x.obj);err(e,ec,"DDC volume query failed");return 0;}if(v>m){CFRelease(x.obj);err(e,ec,"volume exceeds monitor maximum");return 0;}int ok=ddc(&x,0x62,1,v,&c,&m);CFRelease(x.obj);if(!ok)err(e,ec,"DDC volume set/readback failed");return ok;}
int ddc_set_mute(const char*id,int muted,char*e,size_t ec){uint16_t c,m;if(id&&!strncmp(id,"direct:",7)){if(!lock())return 0;Direct x={0};if(!directByID(id,&x,e,ec))return 0;int ok=directVCP(&x,0x8d,1,muted?1:2,&c,&m);CFRelease(x.obj);if(!ok)err(e,ec,"direct DDC mute feature is unsupported or failed");return ok;}Branch x;if(!withBranch(id,&x,e,ec))return 0;int ok=ddc(&x,0x8d,1,muted?1:2,&c,&m);CFRelease(x.obj);if(!ok)err(e,ec,"DDC mute feature is unsupported or failed");return ok;}
int ddc_get_mute(const char*id,int*muted,char*e,size_t ec){uint16_t c=0,m=0;if(!muted){err(e,ec,"invalid mute output");return 0;}int ok=0;if(id&&!strncmp(id,"direct:",7)){if(!lock())return 0;Direct x={0};if(directByID(id,&x,e,ec)){ok=directVCP(&x,0x8d,0,0,&c,&m);CFRelease(x.obj);}}else{Branch x;if(withBranch(id,&x,e,ec)){ok=ddc(&x,0x8d,0,0,&c,&m);CFRelease(x.obj);}}if(!ok){err(e,ec,"DDC mute status is unavailable");return 0;}if(c!=1&&c!=2){err(e,ec,"monitor returned an unknown DDC mute value");return 0;}*muted=c==1;return 1;}
